package org.rabochaya.maptests;
import android.app.*;import android.content.*;import android.view.*;import java.util.*;import org.w3c.dom.Element;
/** Synthetic move confirmations; every rotation must destroy the previous Activity. */
final class ManagerMoveChecks {
 final MapAndroidChecks m;final ManagerVisualChecks v;final ManagerRotationChecks r;
 final Set<String> chosen=new HashSet<>(Arrays.asList("1","2"));
 ManagerMoveChecks(MapAndroidChecks m){this.m=m;v=new ManagerVisualChecks(m);r=new ManagerRotationChecks(m);}
 long insert(Object store)throws Exception{Object doc=r.parse(ManagerRotationChecks.XML.getBytes("UTF-8"));for(String id:new String[]{"point","nested","other"})m.staticCall("MediaLinks","add",new Class[]{m.codec,Element.class,String.class,String.class,byte[].class},doc,m.element(doc,id),id+".jpg","image/jpeg",new byte[]{3,6,9});return (Long)m.call(store,"insert",new Class[]{m.codec,String.class},doc,"QA_MOVE_STATE");}
 Map<String,?> prefs(){return new HashMap<>(m.getTargetContext().getSharedPreferences("object-manager-view",0).getAll());}
 void open(long id)throws Exception{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_FREEZE_0);v.launch(id);v.rotate(UiAutomation.ROTATION_FREEZE_0);m.click("QA_ROTATE_POINT");m.click("QA_ROTATE_OTHER");m.setListingForm("QA_ROTATE_POINT",0,0,0,false,false,0);m.check(new HashSet<>(m.managerKeys("selected")).equals(chosen),"visible and hidden move selection fixture");m.check(m.managerKeys("visible").equals(Arrays.asList("1")),"one selected source outside filtered list");m.managerAction("Перенести выбранное");m.click("Корень проекта / QA_ROTATE_FOLDER");}
 boolean confirmEnabled(){final boolean[] enabled={false};m.runOnMainSync(()->{View button=v.button(m.activeDialogRoot(),"Перенести");enabled[0]=button!=null&&button.isEnabled();});return enabled[0];}
 void identity(long id,String token)throws Exception{Object draft=m.managerField("moveDraft");m.check(draft!=null,"move confirmation draft present");Class<?> c=draft.getClass();m.check(c.getField("project").getLong(draft)==id&&token.equals(c.getField("token").get(draft))&&"0".equals(c.getField("destination").get(draft))&&"Корень проекта / QA_ROTATE_FOLDER".equals(c.getField("label").get(draft))&&c.getField("outside").getInt(draft)==1,"original project/token/destination/label/hidden count retained");m.check(Arrays.equals((int[])c.getMethod("indices").invoke(draft),new int[]{2,3}),"original compact source addresses retained");}
 void rotate(int direction,String scene,long id,String token,boolean enabled)throws Exception{Activity old=m.activity;v.rotate(direction);m.check(old!=m.activity&&old.isDestroyed(),"move Activity actually destroyed: "+scene);identity(id,token);m.check(confirmEnabled()==enabled,"move confirmation enabled only for original unchanged XML");v.controlReachable("Перенести");v.controlReachable("Отмена");v.snapshot(scene,false);}
 void scenario(Object store,String outcome)throws Exception{long id=insert(store);try{Object doc=r.load(store,id);byte[] before=r.xml(doc);String token=m.treeToken(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));open(id);Map<String,?> applied=prefs();identity(id,token);m.check(confirmEnabled(),"initial move requires explicit confirmation");if(outcome.equals("cancel"))v.snapshot("move-state-before",false);if(outcome.equals("stale-before"))r.externalChange(store,id,true);byte[] current=r.xml(r.load(store,id));rotate(UiAutomation.ROTATION_FREEZE_90,"move-state-"+outcome,id,token,!outcome.equals("stale-before"));m.check(Arrays.equals(current,r.xml(r.load(store,id))),"recreating a move confirmation never writes KML");r.sameAssets(r.load(store,id),assets);
  if(outcome.equals("stale-before")){m.waitText("Перенос заблокирован");m.check(m.managerKeys("selected").isEmpty(),"changed XML never rebinds selected sources");m.click("Отмена");m.check(Arrays.equals(current,r.xml(r.load(store,id))),"stale Cancel retains newer document");}
  else{m.check(new HashSet<>(m.managerKeys("selected")).equals(chosen),"unchanged visible/hidden sources remain selected");if(outcome.equals("cancel")){rotate(UiAutomation.ROTATION_FREEZE_0,"move-state-return",id,token,true);m.click("Отмена");m.check(Arrays.equals(before,r.xml(r.load(store,id)))&&applied.equals(prefs()),"Cancel after both rotations retains KML and applied view settings");}
   else if(outcome.equals("save")){Object expected=r.parse(before);m.staticCall("ObjectTree","move",new Class[]{Element.class,Collection.class,String.class,String.class},m.call(expected,"root",new Class[]{}),new ArrayList<>(chosen),"0",token);m.click("Перенести");m.geometryReady();m.waitText("Изменения сохранены");m.check(m.treeToken(expected).equals(m.treeToken(r.load(store,id))),"explicit Move changes only original selected subtrees and target order");m.check(m.managerKeys("selected").isEmpty(),"successful move clears obsolete source addresses");m.check(m.managerField("moveDraft")==null,"successful move closes pending confirmation");v.snapshot("move-state-saved",false);}
   else{r.externalChange(store,id,false);byte[] newer=r.xml(r.load(store,id));m.click("Перенести");m.geometryReady();m.waitText("Проект изменился");v.snapshot("move-state-rejected",false);m.click("Понятно");identity(id,token);m.check(Arrays.equals(newer,r.xml(r.load(store,id))),"transaction rejects stale Move without overwriting newer XML");rotate(UiAutomation.ROTATION_FREEZE_0,"move-state-stale-after-return",id,token,false);m.click("Отмена");m.check(Arrays.equals(newer,r.xml(r.load(store,id))),"Cancel after rejected Move retains newer XML");}
  }
  r.sameAssets(r.load(store,id),assets);m.check(m.managerField("moveDraft")==null,"Cancel/Move removes active draft");Activity old=m.activity;v.rotate(m.activity.getResources().getConfiguration().orientation==1?UiAutomation.ROTATION_FREEZE_90:UiAutomation.ROTATION_FREEZE_0);m.check(old!=m.activity&&old.isDestroyed(),"dismissed move main Activity really recreated");m.check(m.managerField("moveDraft")==null,"dismissed move is never reopened");v.emit("MOVE_STATE_RESULT outcome="+outcome+" PASS");
 }finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void foreign(Object store)throws Exception{long source=insert(store),other=-1;try{Object doc=r.load(store,source);byte[] before=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));Object copy=r.parse(before);m.assets(copy).putAll(assets);other=(Long)m.call(store,"insert",new Class[]{m.codec,String.class},copy,"QA_MOVE_FOREIGN");m.check(m.treeToken(doc).equals(m.treeToken(r.load(store,other))),"foreign project has identical XML token");open(source);final long target=other;m.runOnMainSync(()->m.activity.setIntent(new Intent(m.activity.getIntent()).putExtra("project",target)));Activity old=m.activity;v.rotate(UiAutomation.ROTATION_FREEZE_90);m.check(old!=m.activity&&old.isDestroyed(),"foreign move Activity actually recreated");m.check(((Long)m.managerField("project"))==other&&m.managerField("moveDraft")==null&&m.managerKeys("selected").isEmpty(),"foreign project never restores a pending destructive confirmation");v.snapshot("move-state-foreign",false);m.check(Arrays.equals(before,r.xml(r.load(store,source)))&&Arrays.equals(before,r.xml(r.load(store,other))),"foreign guard retains both documents");r.sameAssets(r.load(store,source),assets);r.sameAssets(r.load(store,other),assets);v.emit("MOVE_STATE_FOREIGN PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},source);if(other>0)m.call(store,"remove",new Class[]{long.class},other);}}
 void run()throws Exception{m.installTileFixture();int requests=m.requests.get();Object store=m.storeClass.getConstructor(Context.class).newInstance(m.getTargetContext());try{for(String outcome:new String[]{"cancel","save","stale-before","stale-after"})scenario(store,outcome);foreign(store);m.check(m.requests.get()==requests,"move confirmation/recreation never sends tile requests");}finally{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);m.call(store,"close",new Class[]{});}}
}
